<script setup lang="ts">
import { getCreateToken, setCreateToken } from '@tmt/browser-client'; import { buildLink, newDocId, newKey, parseLink, trimSlash } from '@tmt/shared'; import { ref, watch } from 'vue'; import { useToast } from '../lib/toast'
const toast = useToast(), input = ref(''), defaultServer = import.meta.env.VITE_DEFAULT_SERVER ?? '', server = ref(defaultServer), token = ref('')
watch(server, (value) => token.value = getCreateToken(trimSlash(value.trim())), { immediate: true })
function open() { const link = parseLink(input.value.trim(), defaultServer || undefined); if (!link) return toast.error('That does not look like a project link.'); location.hash = new URL(buildLink(location.origin + location.pathname, link)).hash }
function create() { const link = parseLink(`#d=${newDocId()}&k=${newKey()}&s=${encodeURIComponent(server.value.trim())}`); if (!link) return toast.error('Enter an http(s) sync server URL.'); setCreateToken(link.server, token.value.trim()); sessionStorage.setItem(`tmt:init:${link.docId}`, 'markdown'); location.hash = new URL(buildLink(location.origin + location.pathname, link)).hash }
</script>
<template><div class="flex min-h-dvh items-center justify-center bg-base-200 p-4"><div class="card w-full max-w-md bg-base-100 shadow-sm"><div class="card-body gap-4"><h1 class="card-title">Markdown editor</h1><form class="flex flex-col gap-2" @submit.prevent="open"><label class="label" for="link">Project link</label><input id="link" v-model="input" class="input w-full" placeholder="https://…/#d=…" /><button class="btn btn-primary">Open</button></form><div class="divider my-0">or</div><form class="flex flex-col gap-2" @submit.prevent="create"><label class="label" for="server">Sync server</label><input id="server" v-model="server" class="input w-full" inputmode="url" placeholder="https://sync.example.org" /><label class="label" for="token">Create token</label><input id="token" v-model="token" class="input w-full" type="password" autocomplete="off" /><button class="btn">New Markdown project</button></form></div></div></div></template>
